    Big r;
    unsigned int carry = 0;
    size_t n = x.size() > y.size() ? x.size() : y.size();
    for (size_t i = 0; i < n; ++i) {
        unsigned long long s = carry;
        if (i < x.size()) s += x[i];
        if (i < y.size()) s += y[i];
        r.push_back((unsigned int)(s % 1000000000ULL));
        carry = (unsigned int)(s / 1000000000ULL);
    }
    if (carry) r.push_back(carry);
    return r;
}

static void print(const Big& v) {
    std::printf("%u", v.back());
    for (size_t i = v.size() - 1; i-- > 0; ) std::printf("%09u", v[i]);
    std::printf("\n");
}

int main(int argc, char** argv) {
    long n = argc > 1 ? std::atol(argv[1]) : 0;
    Big a(1, 1u), b(1, 1u);
    for (long i = 0; i < n; ++i) {
        Big c = add(a, b);
        a = b;
        b = c;
    }
    print(a);
    return 0;
}
