    let mut r: Vec<u32> = Vec::new(); // \
    let mut carry: u64 = 0; // \
    let n = x.len().max(y.len()); // \
    for i in 0..n { // \
        let mut s: u64 = carry; // \
        if i < x.len() { s += x[i] as u64; } // \
        if i < y.len() { s += y[i] as u64; } // \
        r.push((s % 1_000_000_000) as u32); // \
        carry = s / 1_000_000_000; // \
    } // \
    if carry > 0 { r.push(carry as u32); } // \
    r // \
} // \
fn main() { // \
    let n: usize = std::env::args().nth(1).map(|s| s.parse().unwrap()).unwrap_or(0); // \
    let mut a: Vec<u32> = vec![1u32]; // \
    let mut b: Vec<u32> = vec![1u32]; // \
    for _ in 0..n { // \
        let c = add(&a, &b); // \
        a = b; // \
        b = c; // \
    } // \
    let mut out = a.last().unwrap().to_string(); // \
    for i in (0..a.len() - 1).rev() { // \
        out.push_str(&format!("{:09}", a[i])); // \
    } // \
    println!("{}", out); // \
}
